css:
:root {
  --bg-base: #0a0a0a;
  --bg-surface: #111111;
  --bg-card: #1f1f1f;
  --border: #2a2a2a;
  --text: #fafafa;
  --text-muted: #a1a1aa;
  --accent: #0ea5e9;
  --success: #22c55e;
  --danger: #ef4444;
  --warning: #f59e0b;

  /* Uma cor por fonte de receita — a mesma em pílula, gráfico e avatar. */
  --src-empresa: #0ea5e9;
  --src-impressionart: #8b5cf6;
  --src-moto: #f59e0b;
  --src-mos: #22c55e;

  --fonte: 'Manrope', sans-serif;
  --fonte-titulo: 'Sora', sans-serif;
  --fonte-mono: 'JetBrains Mono', monospace;
}

body { background: var(--bg-base); color: var(--text); font-family: var(--fonte); }

/* Número em tabela, card ou badge nunca "dança" ao atualizar. */
.bs-num { font-variant-numeric: tabular-nums; }

.bs-vazio {
  width: min(460px, 100%);
  padding: 40px 20px; text-align: center;
  /* A única borda tracejada do sistema: diz "cabe conteúdo aqui" sem texto. */
  border: 1px dashed var(--border); border-radius: 10px; background: var(--bg-base);
}

.bs-vazio-ic {
  display: grid; place-items: center;
  width: 56px; height: 56px; margin: 0 auto 16px;
  border: 1px solid var(--border); border-radius: 16px; background: var(--bg-card);
}
.bs-vazio-svg { width: 26px; height: 26px; color: var(--text-muted); }

.bs-vazio-titulo {
  margin-bottom: 6px;
  font-family: var(--fonte-titulo); font-size: 16px; font-weight: 600; color: var(--text);
}
.bs-vazio-desc {
  max-width: 280px; margin: 0 auto 20px;
  font-size: 13px; line-height: 1.6; color: var(--text-muted);
}

.bs-vazio-btn {
  padding: 10px 18px; border: none; border-radius: 8px;
  font-family: var(--fonte); font-size: 13px; font-weight: 600;
  color: var(--bg-base); background: var(--accent);
}
.bs-vazio-btn:hover { background: #38bdf8; }
